#!/bin/sh
#
# wp

ALPHA=0.95
# wp is sym link
WP="${XDG_DATA_HOME:-${HOME}/.local/share/}/wp"
# 16 colors generated by pywal
COLORS="${XDG_CACHE_HOME:-${HOME}/.cache/}/wal/colors.sh"
# term fg
DEFAULTFG=259
# xresources handles suckless vars
XRESOURCES="${XDG_CONFIG_HOME:-${HOME}/.config/}/x/xresources"
# file holding system color state
COLOR="${XDG_CACHE_HOME:-${HOME}/.cache/}/dots/color"
# gray wp dir
GRAY_DIR="${XDG_CACHE_HOME:-${HOME}/.cache/}/dots/gray/"

# get random valid file in dir
get_rand_file() {
    # get all files in dir
    files="$(for file in "${1}"/*; do
                [ -d "${file}" ] && continue
                printf '%s\n' "${file}"
            done)"

    # loop until valid file found
    file=''
    while ! check_file "${file}"; do
        # get random file and remove it from list
        file="$(printf '%s' "${files}" | awk 'BEGIN{ srand() } { printf "%f %s\n", rand(), $0 }' | sort | cut -d ' ' -f 2 | head -n 1)"
        files="$(printf '%s' "${files}" | grep -iv "${file}")"

        # break if no more files to check
        [ -z "${files}" ] && break
    done

    # no files in dir are valid
    if ! check_file "${file}"; then file=''; fi

    if [ -z "${file}" ]; then return 1
    else return 0
    fi
}

check_file () {
    # get file extension
    file="${1}"
    ext="${file##*.}"

    case "${ext}" in
        # formats supported by imlib2 used by feh, sxiv, etc.
        bmp  \
      | dib  \
      | ff   \
      | gif  \
      | ico  \
      | iff  \
      | jfi  \
      | jfif \
      | jif  \
      | jpe  \
      | jpeg \
      | jpg  \
      | lbm  \
      | png  \
      | pnm  \
      | tga  \
      | tif  \
      | tiff \
      | webp \
      | xpm) return   ;;
        *)   return 1 ;;
    esac
}

wp () {
    # get system color state (0 = grayscale, 1 = rgb)
    mode="$(cat "${COLOR}")"

    # rgb
    if [ "${mode}" -eq 1 ]; then
        # create wp sym link as normal
        ln -sf "${file}" "${WP}"
    else
        # gen grayscale wp
        ext="${file##*.}"
        gray="${GRAY_DIR}/$(basename "${file%.*}-gray.${ext}")"
        if [ -e "${GRAY_DIR}" ]; then
            rm -rf "${GRAY_DIR}"
            mkdir "${GRAY_DIR}"
        fi
        magick "${file}" -colorspace Gray "${gray}" >/dev/null 2>&1

        # use grayscale wp as normal symlink and color wp as bak
        ln -sf "${gray}" "${WP}"
        ln -sf "${file}" "${WP}.bak"
    fi

    # change bg
    feh --no-fehbg --bg-scale "${WP}"

    # theme iff pywal installed
    command -v wal >/dev/null && theme
}

theme() {
    # remove cached themes
    wal -c

    # gen new theme with wpg (uses pywal)
    wpg -a "${file}" && wpg -ns "${file}"

    [ -f "${COLORS}" ] && . "${COLORS}"

    set -- "${color0}" "${color1}" "${color2}" "${color3}" "${color4}" "${color5}" "${color6}" "${color7}" \
           "${color8}" "${color9}" "${color10}" "${color11}" "${color12}" "${color13}" "${color14}" "${color15}"

    # replace colors in xresources
    i=0
    for color in "${@}"; do
        color="$(printf '%s' "${color}" | tr '[:upper:]' '[:lower:]')"
        printf '%s\n' "$(sed "s/#define col${i} .*/#define col${i} ${color}/" "${XRESOURCES}")" > "${XRESOURCES}"
        i=$((i+1))
        [ ${i} -eq 16 ] && break
    done

    # reload xresources
    xrdb "${XRESOURCES}"

    # firefox; python-pywalfox and firefox plugin are required
    # palette and theme templates have to be set up in firefox itself
    # see https://github.com/frewacom/pywalfox
    pywalfox dark
    pywalfox update

    # reload all instances of term
    kill -s USR1 $(ps -ef | grep -i "\<${TERMINAL}\>" | grep -v '\<grep\>' | awk '{ printf "%s ", $2 }')

    # hacky work-around to change terminal fg on the fly
    # buggy with alpha
    for tty in $(find /dev/pts/ -name '*' | grep '[1-9][0-9]*' | tr -d '[:alpha:][=/=]'); do
        echo "\033]4;${DEFAULTFG};${color0}\007" > "/dev/pts/${tty}" 2>/dev/null
    done

    # reload dwm
    dwmc reload

    # zathura
    zathura-pywal -a ${ALPHA}
}

main() {
    # convert relative to abs if not already
    case "${1}" in
        /*) path="${1}"        ;;
        *)  path="${PWD}/${1}" ;;
    esac

    # handle symlinks
    path="$("${HOME}/.local/bin/symlink.sh" "${path}")"

    # if dir get rand file
    if [ -d "${path}" ]; then
        get_rand_file "${path}" && wp "${file}"
    # if file check it
    elif [ -f "${path}" ]; then
        check_file "${path}" && wp "${file}"
    else return 1
    fi
}

main "${@}"
